------------ lifeCycle ------------
function LadderStruggleRecordCell:Awake()
    self:CleanProperties()
    self:InitComponent()
end

function LadderStruggleRecordCell:OnDestroy()
    self:CleanProperties()
    self.controller = nil
    self = nil
end
------------ lifeCycle ------------

function LadderStruggleRecordCell:CleanProperties()
    self.videoId = nil
    self.playerTeam = nil
    self.enemyTeam = nil
    self.systemName = nil
    self.component = nil
end

function LadderStruggleRecordCell:SetSystem(systemName)
    self.systemName = systemName
    self.component = GameUtils.GetECSComponentBySystemName(systemName)
end

function LadderStruggleRecordCell:InitComponent()
    SetButtonAction(self.Btn_Detail, Bind(self, self.OnDetailBtnClicked))
    if IsNull(self.LB_PlayerHead.Env) then
        self.LB_PlayerHead:Init()
    end
end

function LadderStruggleRecordCell:OnDetailBtnClicked()
    -- UIModule.CloseDialog(UIModule.CurrentScreen:LastDialog())
    -- UIModule.OpenDialog({ id = Constants.UITypeIds.LadderStruggleRecordPopup}, {{ id = Constants.UITypeIds.LadderStruggleRecordDialog }})
    UIModule.OpenDialog({ id = self.component.UIRecordPopup, 
        parameters = {
            videoId = self.videoId, 
            systemName = self.systemName,
            playerTeam = self.playerTeam,
            enemyTeam = self.enemyTeam,
        }
    })
end

function LadderStruggleRecordCell:UpdateData(data)
    if isNull(data) then
        return
    end

    local rank = data.rank
    local playerName = data.name
    local level = data.level
    local avatarId = checkInt(data.avatar)
    local avatarFrameId = checkInt(data.avatarFrame)
    local combatValue = data.combatValue
    local battleResult = data.battleResult
    local attackOrDefence = data.attackOrDefence
    local rankChangeState = data.rankChangeState
    local rankChange = data.rankChange
    local createTime = checkNumber(data.createTime)

    self.videoId = data.videoId
    self.playerTeam = data.playerTeam
    self.enemyTeam = data.enemyTeam

    self.Txt_Rank.text = tostring(rank)
    self.Txt_CombatValue.text = tostring(combatValue)
    self.Txt_Level.text = tostring(level)
    self.Txt_PlayerName.text = playerName
    self.LB_PlayerHead.Env:FreshAvatarFrame(avatarId, avatarFrameId)
    self.SImg_Result.Status = battleResult
    KTool.SetActive(self.RT_Attack, attackOrDefence == 1)
    KTool.SetActive(self.RT_Defence, attackOrDefence == 2)
    KTool.SetActive(self.RT_RankFloatArrow, true)
    self.Simg_RankFloatArrow.Status = rankChangeState
    self.Simg_RankFloatText.Status = rankChangeState
    self.Txt_RankFloatText.text = tostring(rankChange)
    KTool.SetActive(self.Simg_RankFloatText, rankChangeState ~= 3)

    local recordTime = localize("刚刚")
    if createTime > 60 then
        recordTime = CfUtils.GetTimeHMS10(createTime) .. localize("前")
    end
    CfUtils.FillText(self.Btn_Detail.transform:Find("TxtTime"), recordTime)
end

return LadderStruggleRecordCell